import{_ as o,r as a,o as p,c as r,e as n,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Import Export Controller - October CMS - 3.x","titleTemplate":false,"description":"Adds importing and exporting features to a page.","frontmatter":{"subtitle":"Adds importing and exporting features to a page."},"headers":[{"level":2,"title":"Configuring the Behavior","slug":"configuring-the-behavior","link":"#configuring-the-behavior","children":[{"level":3,"title":"Import Page","slug":"import-page","link":"#import-page","children":[]},{"level":3,"title":"Export Page","slug":"export-page","link":"#export-page","children":[]},{"level":3,"title":"Format Options","slug":"format-options","link":"#format-options","children":[]}]},{"level":2,"title":"Import and Export Views","slug":"import-and-export-views","link":"#import-and-export-views","children":[{"level":3,"title":"Import View","slug":"import-view","link":"#import-view","children":[]},{"level":3,"title":"Export View","slug":"export-view","link":"#export-view","children":[]}]},{"level":2,"title":"Integration with List Behavior","slug":"integration-with-list-behavior","link":"#integration-with-list-behavior","children":[]}],"relativePath":"3.x/extend/importexport/importexport-controller.md","filePath":"3.x/extend/importexport/importexport-controller.md"}'),i={name:"3.x/extend/importexport/importexport-controller.md"};function u(d,t,k,g,m,h){const s=a("pre-heading"),e=a("post-heading");return p(),r("div",null,[n(s),t[0]||(t[0]=l("h1",null,"Import Export Controller",-1)),n(e),t[1]||(t[1]=c(`<p>The <code>Backend\\Behaviors\\ImportExportController</code> class is a controller behavior that provides features for importing and exporting data. The behavior provides two pages called Import and Export. The Import page allows a user to upload a CSV file and match the columns to the database. The Export page is the opposite and allows a user to download columns from the database as a CSV file. The behavior provides the controller actions <code>import()</code> and <code>export()</code>.</p><p>The importing and exporting behavior configuration is defined in two parts, each part depends on a special model class along with a list and form field definition file. To use the behavior you should add it to the <code>$implement</code> property of the controller class. Also, the <code>$importExportConfig</code> class property should be defined and its value should refer to the YAML file used for configuring the behavior properties.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Shop<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Products</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ImportExportController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$importExportConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_import_export.yaml&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// [...]</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="configuring-the-behavior"><a href="#configuring-the-behavior" class="header-anchor">#</a> Configuring the Behavior</h2><p>The configuration file referred in the <code>$importExportConfig</code> property is defined in YAML format. The file should be placed into the controller&#39;s <a href="./../system/views.html">views directory</a>. Below is an example of a configuration file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_import_export.yaml</span>
<span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml

<span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml
</code></pre></div><p>The configuration properties listed below are optional. Define them if you want the behavior to support the import page or export page, or both.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>defaultRedirect</strong></td><td>used as a fallback redirection page when no specific redirect page is defined.</td></tr><tr><td><strong>import</strong></td><td>a configuration array or reference to a config file for the Import page.</td></tr><tr><td><strong>export</strong></td><td>a configuration array or reference to a config file for the Export page.</td></tr><tr><td><strong>defaultFormatOptions</strong></td><td>a configuration array or reference to a config file for the default CSV format options.</td></tr></tbody></table></div><h3 id="import-page"><a href="#import-page" class="header-anchor">#</a> Import Page</h3><p>To support the Import page add the following configuration to the YAML file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberimport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>The following configuration properties are supported for the Import page.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a page title, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>list</strong></td><td>defines the list columns available for importing.</td></tr><tr><td><strong>form</strong></td><td>provides additional fields used as import options, optional.</td></tr><tr><td><strong>redirect</strong></td><td>redirection page when the import is complete, optional</td></tr><tr><td><strong>permissions</strong></td><td>user permissions needed to perform the operation, optional</td></tr></tbody></table></div><h3 id="export-page"><a href="#export-page" class="header-anchor">#</a> Export Page</h3><p>To support the Export page add the following configuration to the YAML file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberexport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>The following configuration properties are supported for the Export page:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a page title, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>fileName</strong></td><td>the file name to use for the exported file without extension. Default <code>export</code></td></tr><tr><td><strong>list</strong></td><td>defines the list columns available for exporting.</td></tr><tr><td><strong>form</strong></td><td>provides additional fields used as export options, optional.</td></tr><tr><td><strong>redirect</strong></td><td>redirection page when the export is complete, optional.</td></tr><tr><td><strong>useList</strong></td><td>set to true or the value of a list definition to enable integration with lists. Default: <code>false</code>.</td></tr></tbody></table></div><h3 id="format-options"><a href="#format-options" class="header-anchor">#</a> Format Options</h3><p>To override the default format options add the following configuration to the YAML file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">defaultFormatOptions</span><span class="token punctuation">:</span>
    <span class="token key atrule">fileFormat</span><span class="token punctuation">:</span> json
</code></pre></div><p>The following configuration properties (all optional) are supported for the format options, including their applicable format type.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th><th>Format</th></tr></thead><tbody><tr><td><strong>fileFormat</strong></td><td>File format as either <code>json</code>, <code>csv</code> or <code>csv_custom</code>, default: <code>json</code>.</td><td></td></tr><tr><td><strong>customJson</strong></td><td>Use a custom format for the <code>json</code> format type.</td><td>JSON</td></tr><tr><td><strong>firstRowTitles</strong></td><td>First row contains headers, import only.</td><td>CSV</td></tr><tr><td><strong>delimiter</strong></td><td>Delimiter character.</td><td>CSV (Custom)</td></tr><tr><td><strong>enclosure</strong></td><td>Enclosure character.</td><td>CSV (Custom)</td></tr><tr><td><strong>escape</strong></td><td>Escape character.</td><td>CSV (Custom)</td></tr><tr><td><strong>encoding</strong></td><td>File encoding, import only.</td><td>CSV (Custom)</td></tr></tbody></table></div><h2 id="import-and-export-views"><a href="#import-and-export-views" class="header-anchor">#</a> Import and Export Views</h2><p>For each page feature import and export you should provide a <a href="./../system/views.html">view file</a> with the corresponding name - <strong>import.htm</strong> and <strong>export.htm</strong>.</p><p>The import/export behavior adds two methods to the controller class: <code>importRender</code> and <code>exportRender</code>. These methods render the importing and exporting sections as per the YAML configuration file described above.</p><h3 id="import-view"><a href="#import-view" class="header-anchor">#</a> Import View</h3><p>The <strong>import.htm</strong> view represents the Import page that allows users to import data. A typical Import page contains breadcrumbs, the import section itself, and the submission buttons. The <strong>data-request</strong> attribute should refer to the <code>onImport</code> AJAX handler provided by the behavior. Below is a contents of the typical import.htm view file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">importRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onImportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Import records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="export-view"><a href="#export-view" class="header-anchor">#</a> Export View</h3><p>The <strong>export.htm</strong> view represents the Export page that allows users to export a file from the database. A typical Export page contains breadcrumbs, the export section itself, and the submission buttons. The <strong>data-request</strong> attribute should refer to the <code>onExport</code> AJAX handler provided by the behavior. Below is a contents of the typical export.htm form.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">exportRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Export records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="integration-with-list-behavior"><a href="#integration-with-list-behavior" class="header-anchor">#</a> Integration with List Behavior</h2><p>There is an alternative approach to exporting data that uses the <a href="./../lists/list-controller.html">list behavior</a> to provide the export data. In order to use this feature you should have the <code>Backend\\Behaviors\\ListController</code> definition to the <code>$implement</code> field of the controller class. You do not need to use an export view and all the settings will be pulled from the list. Here is the only configuration needed:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Then simply add an export button to the <a href="./../lists/list-controller.html">list toolbar</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/campaign/subscribers/export&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default oc-icon-download<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Export Records
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Similarly, to add an import button, the code would look like this:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/campaign/subscribers/import&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default oc-icon-upload<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Import Records
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>If you are using <a href="./../lists/list-controller.html">multiple list definitions</a>, then you can supply the list definition.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> orders
    <span class="token key atrule">fileName</span><span class="token punctuation">:</span> orders.csv
</code></pre></div><p>The <code>useList</code> option also supports extended configuration properties.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span>
        <span class="token key atrule">definition</span><span class="token punctuation">:</span> orders
        <span class="token key atrule">raw</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>The following configuration properties are supported:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>definition</strong></td><td>the list definition to source records from, optional.</td></tr><tr><td><strong>raw</strong></td><td>output the raw attribute values from the record, default: false.</td></tr></tbody></table></div>`,45))])}const b=o(i,[["render",u]]);export{v as __pageData,b as default};
